<?php
require_once __DIR__.'/includes/seguridad.php';require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/modulos_clinica.php';exigirRoles(['admin']);$pdo=getDB();asegurarModulosClinica($pdo);$modulo=trim((string)($_GET['modulo']??''));$sql='SELECT a.*,u.nombre_completo usuario FROM auditoria a LEFT JOIN usuarios u ON u.id=a.usuario_id';$params=[];if($modulo!==''){$sql.=' WHERE a.modulo=:modulo';$params[':modulo']=$modulo;}$sql.=' ORDER BY a.fecha DESC LIMIT 300';$q=$pdo->prepare($sql);$q->execute($params);$registros=$q->fetchAll();$modulos=$pdo->query('SELECT DISTINCT modulo FROM auditoria ORDER BY modulo')->fetchAll(PDO::FETCH_COLUMN);$pageTitle='Auditoría - VetClinic Pro';require_once __DIR__.'/includes/header.php';?>
<div class="page-header"><h3><i class="bi bi-clock-history text-primary me-2"></i>Auditoría</h3><p>Quién realizó cada cambio importante y cuándo.</p></div><div class="card card-stat mb-3"><div class="card-body py-3"><form class="module-toolbar"><select name="modulo" class="form-select w-auto"><option value="">Todos los módulos</option><?php foreach($modulos as $m):?><option <?=$m===$modulo?'selected':''?>><?=e($m)?></option><?php endforeach;?></select><button class="btn btn-primary">Filtrar</button></form></div></div><div class="card card-stat"><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Fecha</th><th>Usuario</th><th>Módulo</th><th>Acción</th><th>Registro</th><th>Detalle</th></tr></thead><tbody><?php foreach($registros as $r):?><tr><td><?=e(date('d/m/Y H:i:s',strtotime($r['fecha'])))?></td><td><?=e($r['usuario']?:'Sistema')?></td><td><span class="badge bg-light text-dark border"><?=e($r['modulo'])?></span></td><td><?=e(str_replace('_',' ',$r['accion']))?></td><td><?=$r['registro_id']?(int)$r['registro_id']:'—'?></td><td><?=e($r['detalle']?:'—')?></td></tr><?php endforeach;?></tbody></table></div></div><?php require_once __DIR__.'/includes/footer.php';?>
